create type public.app_role as enum ('admin','worker');
create type public.worker_status as enum ('pending','active','suspended');
create type public.lead_stage as enum ('new','contacted','interested','follow_up','quoted','won','lost');
create type public.activity_type as enum ('call','whatsapp','email','note','status_change');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'worker',worker_status public.worker_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.activation_codes(id uuid primary key default gen_random_uuid(),code text unique not null,worker_email text not null,created_by uuid references public.profiles(id),used_at timestamptz,expires_at timestamptz not null,created_at timestamptz not null default now());
create table public.work_sessions(id uuid primary key default gen_random_uuid(),worker_id uuid not null references public.profiles(id) on delete cascade,started_at timestamptz not null default now(),ended_at timestamptz,created_at timestamptz not null default now());
create unique index one_open_work_session on public.work_sessions(worker_id) where ended_at is null;
create table public.leads(id uuid primary key default gen_random_uuid(),assigned_to uuid not null references public.profiles(id) on delete cascade,name text not null,phone text,email text,company text,stage public.lead_stage not null default 'new',notes text,next_follow_up_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.activities(id uuid primary key default gen_random_uuid(),worker_id uuid not null references public.profiles(id) on delete cascade,lead_id uuid references public.leads(id) on delete set null,type public.activity_type not null,outcome text,notes text,created_at timestamptz not null default now());
create index leads_assigned_idx on public.leads(assigned_to);create index activities_worker_idx on public.activities(worker_id,created_at);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create trigger leads_updated_at before update on public.leads for each row execute function public.set_updated_at();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create or replace function public.claim_first_admin() returns boolean language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null or exists(select 1 from public.profiles where role='admin') then return false; end if; update public.profiles set role='admin',worker_status='active' where id=auth.uid(); return true; end; $$;
create or replace function public.create_activation_code(p_worker_email text,p_expires_in_hours int default 24) returns text language plpgsql security definer set search_path=public as $$ declare c text; begin if not public.is_admin() then raise exception 'admin only'; end if; c=upper(substr(md5(random()::text||clock_timestamp()::text),1,10)); insert into public.activation_codes(code,worker_email,created_by,expires_at) values(c,lower(trim(p_worker_email)),auth.uid(),now()+make_interval(hours=>p_expires_in_hours)); return c; end; $$;
create or replace function public.activate_worker(p_code text) returns boolean language plpgsql security definer set search_path=public as $$ declare ok boolean; em text; begin select email into em from auth.users where id=auth.uid(); select exists(select 1 from public.activation_codes where code=upper(trim(p_code)) and lower(worker_email)=lower(em) and used_at is null and expires_at>now()) into ok; if not ok then raise exception 'invalid or expired activation code'; end if; update public.activation_codes set used_at=now() where code=upper(trim(p_code)) and used_at is null; update public.profiles set worker_status='active' where id=auth.uid(); return true; end; $$;
create or replace function public.get_admin_worker_dashboard() returns table(worker_id uuid,worker_name text,worker_status public.worker_status,seconds_worked_today bigint,activities_today bigint,interested_leads bigint,follow_ups_due bigint,conversions bigint,currently_working boolean) language sql security definer set search_path=public as $$ with ws as (select worker_id,coalesce(sum(extract(epoch from(coalesce(ended_at,now())-started_at))),0)::bigint seconds from public.work_sessions where started_at>=date_trunc('day',now()) group by worker_id),ac as(select worker_id,count(*)::bigint n from public.activities where created_at>=date_trunc('day',now()) group by worker_id),il as(select assigned_to,count(*)::bigint n from public.leads where stage='interested' group by assigned_to),fu as(select assigned_to,count(*)::bigint n from public.leads where stage='follow_up' and(next_follow_up_at is null or next_follow_up_at<=now()) group by assigned_to),co as(select assigned_to,count(*)::bigint n from public.leads where stage='won' group by assigned_to),op as(select distinct worker_id from public.work_sessions where ended_at is null) select p.id,p.full_name,p.worker_status,coalesce(ws.seconds,0),coalesce(ac.n,0),coalesce(il.n,0),coalesce(fu.n,0),coalesce(co.n,0),(op.worker_id is not null) from public.profiles p left join ws on ws.worker_id=p.id left join ac on ac.worker_id=p.id left join il on il.assigned_to=p.id left join fu on fu.assigned_to=p.id left join co on co.assigned_to=p.id left join op on op.worker_id=p.id where p.role='worker' order by p.full_name; $$;
create or replace function public.get_worker_timeline(p_worker_id uuid,p_day date default current_date) returns table(type public.activity_type,outcome text,notes text,created_at timestamptz,lead_name text) language sql security definer set search_path=public as $$ select a.type,a.outcome,a.notes,a.created_at,l.name from public.activities a left join public.leads l on l.id=a.lead_id where public.is_admin() and a.worker_id=p_worker_id and a.created_at>=p_day::timestamptz and a.created_at<(p_day+1)::timestamptz order by a.created_at; $$;
alter table public.profiles enable row level security;alter table public.activation_codes enable row level security;alter table public.work_sessions enable row level security;alter table public.leads enable row level security;alter table public.activities enable row level security;
create policy profiles_self on public.profiles for select using(id=auth.uid() or public.is_admin());create policy profiles_admin_update on public.profiles for update using(public.is_admin()) with check(public.is_admin());
create policy sessions_worker on public.work_sessions for all using(worker_id=auth.uid() or public.is_admin()) with check(worker_id=auth.uid() or public.is_admin());
create policy leads_worker on public.leads for all using(assigned_to=auth.uid() or public.is_admin()) with check(assigned_to=auth.uid() or public.is_admin());
create policy activities_worker on public.activities for all using(worker_id=auth.uid() or public.is_admin()) with check(worker_id=auth.uid() or public.is_admin());
grant execute on function public.claim_first_admin() to authenticated;grant execute on function public.create_activation_code(text,int) to authenticated;grant execute on function public.activate_worker(text) to authenticated;grant execute on function public.get_admin_worker_dashboard() to authenticated;grant execute on function public.get_worker_timeline(uuid,date) to authenticated;